-- Тема 10: уточнения по проверке Codex (36 исправлений в 15 вопросах), ключи не меняются.
-- Источник: scripts/questions/078_codex_topic10_fixes.js
-- Повторный запуск безопасен: вопрос и вариант ищутся по тексту, прежнее или уже новое значение допустимо,
-- иначе пакет отменяется. Ключи ответов, число и порядок вариантов не меняются.

BEGIN;
SET LOCAL standard_conforming_strings = on;
LOCK TABLE questions IN SHARE ROW EXCLUSIVE MODE;

DO $fix$
DECLARE fix record; matches integer; qid integer; k text;
BEGIN
    FOR fix IN SELECT * FROM (VALUES
        ('question', 'Что PostgreSQL создаёт в PGDATA/pg_tblspc для пользовательского табличного пространства?', NULL, NULL, NULL, 'Что PostgreSQL создаёт в PGDATA/pg_tblspc для пользовательского табличного пространства при непустом абсолютном пути LOCATION?'),
        ('question', 'Что верно для табличного пространства по умолчанию баз данных, созданных при инициализации кластера?', NULL, NULL, NULL, 'Что верно для ТП по умолчанию баз данных сразу после initdb при стандартных настройках размещения объектов?'),
        ('question', 'Что нужно, чтобы удалить табличное пространство командой DROP TABLESPACE?', NULL, NULL, NULL, 'Какое условие по содержимому пользовательского ТП необходимо для DROP TABLESPACE?'),
        ('option', 'Для чего служат табличные пространства?', 'Ограничивают права пользователей на объекты', NULL, 'Права задаются привилегиями.', 'Права на сами таблицы задаются привилегиями. У табличного пространства есть своя привилегия CREATE: она разрешает размещать в нём объекты, но не даёт доступа к данным.'),
        ('option', 'Какие табличные пространства создаются при инициализации кластера?', 'pg_data, pg_wal и pg_xact', 'pg_wal и pg_xact', 'Это не табличные пространства; pg_wal — каталог журнала.', 'Это каталоги журнала и статусов транзакций, а не табличные пространства.'),
        ('option', 'Что хранится в табличном пространстве pg_global?', 'Объекты шаблонной базы template1 и template0', 'Объекты шаблонных баз template1 и template0', 'Объекты template1 изначально лежат в pg_default.', 'Локальные системные каталоги баз template0 и template1 изначально находятся в pg_default.'),
        ('option', 'Что хранится в табличном пространстве pg_global?', 'Общие объекты каталога всего кластера', 'Общие объекты системного каталога кластера', 'Общие для кластера объекты системного каталога: например, базы данных, роли и табличные пространства.', 'В pg_global хранятся общие системные каталоги со сведениями о базах данных, ролях и табличных пространствах.'),
        ('option', 'Что хранится в табличном пространстве pg_global?', 'Журнал предзаписи и архив сегментов WAL', NULL, 'Журнал находится в PGDATA/pg_wal.', 'Рабочие сегменты WAL находятся в PGDATA/pg_wal; место и способ архивирования задаются отдельно. pg_global предназначен для общих системных каталогов.'),
        ('option', 'Что PostgreSQL создаёт в PGDATA/pg_tblspc для пользовательского табличного пространства при непустом абсолютном пути LOCATION?', 'Символическую ссылку на его каталог', NULL, 'Ссылка с именем-oid ведёт на каталог табличного пространства.', 'Создаётся ссылка с именем, равным OID пространства, на каталог из LOCATION. Тестовый режим allow_in_place_tablespaces с пустым LOCATION создаёт каталог непосредственно в pg_tblspc.'),
        ('option', 'Что PostgreSQL создаёт в PGDATA/pg_tblspc для пользовательского табличного пространства при непустом абсолютном пути LOCATION?', 'Отдельный архив WAL для его объектов', NULL, 'Архив WAL с табличными пространствами не связан.', 'CREATE TABLESPACE не создаёт отдельного архива WAL для этого пространства: WAL относится ко всему кластеру, а архивирование настраивается отдельно.'),
        ('option', 'Зачем внутри каталога пользовательского ТП есть подкаталог с версией сервера?', 'Для удобства обновления сервера на другую версию', 'Для удобного перехода на другую версию сервера', 'Старая и новая версии могут временно жить в одном каталоге, например при pg_upgrade.', NULL),
        ('option', 'Зачем внутри каталога пользовательского ТП есть подкаталог с версией сервера?', 'Это имя базы данных внутри кластера', 'Для выбора базы при подключении к серверу', 'Подкаталоги баз находятся уже внутри него.', 'Базы выбирают при подключении клиента, а подкаталоги баз находятся уже внутри каталога версии.'),
        ('option', 'Может ли одна база данных хранить объекты в нескольких табличных пространствах?', 'Нет, все объекты базы лежат в одном ТП', 'Нет, пространство выбирается для базы целиком', 'Можно и в нескольких.', NULL),
        ('option', 'Может ли одна база данных хранить объекты в нескольких табличных пространствах?', 'Да, объекты можно размещать в разных ТП', 'Да, разным объектам можно назначить разные ТП', 'У базы есть табличное пространство по умолчанию, а для отдельных объектов место хранения указывают при создании.', NULL),
        ('option', 'Может ли одна база данных хранить объекты в нескольких табличных пространствах?', 'Да, если её владелец — суперпользователь', 'Нет, разные ТП предназначены для разных баз', 'Владелец базы здесь роли не играет.', 'Между базами и ТП нет соответствия один к одному: одна база может использовать несколько ТП, а одно ТП — несколько баз. Для размещения объекта учитываются права создающей его роли, включая CREATE на выбранное пространство.'),
        ('option', 'Где хранятся объекты системного каталога конкретной базы данных?', 'В PGDATA/pg_tblspc', 'В каталоге ссылок PGDATA/pg_tblspc', 'Там только ссылки на табличные пространства.', NULL),
        ('option', 'Где хранятся объекты системного каталога конкретной базы данных?', 'В табличном пространстве по умолчанию этой базы', 'В ТП по умолчанию этой базы данных кластера', 'Пользовательские объекты при этом могут лежать и в других ТП.', NULL),
        ('option', 'Какое табличное пространство становится ТП по умолчанию для новой базы, если TABLESPACE не указан?', 'Табличное пространство базы-шаблона', 'Табличное пространство базы-шаблона при клонировании', 'База получает табличное пространство шаблона, из которого она клонируется.', NULL),
        ('option', 'Какое табличное пространство становится ТП по умолчанию для новой базы, если TABLESPACE не указан?', 'Никакое: база создаётся без ТП по умолчанию', 'Пространство из параметра default_tablespace', 'У базы всегда есть табличное пространство по умолчанию.', 'default_tablespace влияет на создание объектов внутри базы, но не выбирает ТП новой базы: она наследует ТП шаблона.'),
        ('option', 'Какой сценарий типичен для табличных пространств?', 'Архив — на медленных дисках, активные — на быстрых', 'Размещение данных на дисках разной скорости', 'Данные размещаются на дисках разной скорости.', NULL),
        ('option', 'Какой сценарий типичен для табличных пространств?', 'Разделение прав между разными пользователями', 'Задают права SELECT на размещённые таблицы', 'Права задаются привилегиями.', 'CREATE на табличное пространство разрешает размещать в нём объекты; SELECT на таблицы задаётся отдельно.'),
        ('option', 'Какой сценарий типичен для табличных пространств?', 'Ускорение физической репликации на реплики', NULL, 'К репликации это не относится.', 'ТП выбирает место хранения данных; ускорением физической репликации оно не занимается, WAL реплика получает независимо от того, где лежат её файлы.'),
        ('option', 'Что верно для ТП по умолчанию баз данных сразу после initdb при стандартных настройках размещения объектов?', 'В нём создаются объекты, если ТП не указано явно', NULL, 'При стандартных настройках: если не указано другое и не задан default_tablespace.', 'Если TABLESPACE не указан и параметры default_tablespace и temp_tablespaces не выбирают другое пространство, используется ТП базы. Для обычных и временных объектов действуют разные параметры размещения.'),
        ('option', 'Что верно для ТП по умолчанию баз данных сразу после initdb при стандартных настройках размещения объектов?', 'Его нельзя изменить после создания базы', 'Его меняют командой ALTER TABLESPACE', 'Можно изменить командой ALTER DATABASE ... SET TABLESPACE.', 'ТП по умолчанию базы меняет ALTER DATABASE ... SET TABLESPACE; ALTER TABLESPACE меняет свойства самого ТП, а не выбор для базы.'),
        ('option', 'Что верно для табличных пространств?', 'Табличное пространство нельзя удалить командой SQL', 'Удаление ТП выполняют командой DROP DATABASE', 'Пустое табличное пространство удаляет DROP TABLESPACE.', 'Пустое табличное пространство удаляет DROP TABLESPACE; DROP DATABASE удаляет базу.'),
        ('option', 'Что верно для табличных пространств?', 'Одна база может хранить объекты в разных ТП', 'Объекты одной базы размещаются в разных ТП', 'Отдельные объекты можно размещать в других ТП.', NULL),
        ('option', 'Что верно для табличных пространств?', 'Схема и табличное пространство — одно и то же понятие', 'При создании ТП создаётся одноимённая схема', 'Схема — логическое понятие, табличное пространство — физическое.', 'Схема — логическое понятие, табличное пространство — физическое: одноимённая схема не создаётся.'),
        ('option', 'Что верно для табличных пространств?', 'Одно табличное пространство могут использовать разные базы', 'Одно ТП используется объектами разных баз', 'Табличное пространство не принадлежит одной базе.', NULL),
        ('option', 'Где на диске находятся стандартные табличные пространства?', 'Пользовательские — внутри PGDATA/base', 'pg_default — в PGDATA/global', 'Каталог пользовательского ТП задаётся в LOCATION, обычно вне PGDATA; в pg_tblspc на него ссылка.', 'PGDATA/global соответствует pg_global; pg_default использует PGDATA/base.'),
        ('option', 'Какое условие по содержимому пользовательского ТП необходимо для DROP TABLESPACE?', 'В нём не должно оставаться объектов', 'Освободить пространство от объектов всех баз кластера', 'Непустое табличное пространство удалить нельзя.', NULL),
        ('option', 'Какое условие по содержимому пользовательского ТП необходимо для DROP TABLESPACE?', 'Предварительно удалить его каталог вручную', 'Удалить запись о ТП из pg_tablespace вручную', 'Вручную трогать файлы табличного пространства нельзя.', 'Системный каталог меняет сама команда DROP TABLESPACE; удалять строки вручную нельзя.'),
        ('option', 'Какое условие по содержимому пользовательского ТП необходимо для DROP TABLESPACE?', 'Сначала удалить все базы данных кластера', NULL, 'Достаточно, чтобы в этом пространстве не было объектов.', 'Удалять все базы кластера не требуется. Нужно освободить удаляемое пространство от объектов всех баз; кроме того, нужны права владельца или суперпользователя и выполнение вне блока транзакции. Временные файлы также могут помешать удалению.'),
        ('option', 'Почему внутри PGDATA/global нет подкаталогов баз данных?', 'Его данные относятся ко всему кластеру, а не к базам', 'Здесь хранятся общие объекты кластера', 'Это табличное пространство pg_global с общими объектами каталога.', 'Данные относятся ко всему кластеру, а не к отдельным базам, поэтому подкаталогов баз в PGDATA/global нет. Это табличное пространство pg_global.'),
        ('option', 'Что задают параметры seq_page_cost и random_page_cost?', 'Оценку стоимости чтения страницы для планировщика', 'Оценки стоимости чтения страницы планировщиком', 'Примерную стоимость чтения страницы при последовательном и произвольном доступе; их можно задать и для отдельного табличного пространства.', 'seq_page_cost оценивает чтение страницы при последовательном доступе, random_page_cost — при произвольном; это оценки планировщика в условных единицах, их можно переопределить для отдельного ТП.'),
        ('option', 'Что задают параметры seq_page_cost и random_page_cost?', 'Размер буферного кеша для разных видов чтения', NULL, 'Это параметр shared_buffers.', 'shared_buffers задаёт общий размер буферного кеша; отдельные размеры для этих двух видов чтения такими параметрами не задаются.'),
        ('option', 'Что задают параметры seq_page_cost и random_page_cost?', 'Предельную скорость чтения с диска сервером', NULL, 'Параметры меняют только оценки планировщика, а не работу дисков.', 'Параметры не устанавливают предел скорости диска: они меняют лишь оценки планировщика.')
    ) AS fixes(kind, question_text, opt_text, new_opt_text, old_text, new_text)
    LOOP
        -- Сначала ровно один вопрос по тексту (прежнему или новому), дальше всё только по его id.
        SELECT count(*), min(id) INTO matches, qid FROM questions
        WHERE question_text IN (fix.question_text, CASE WHEN fix.kind = 'question' THEN fix.new_text ELSE fix.question_text END);
        IF matches <> 1 THEN RAISE EXCEPTION 'Не найден единственный вопрос для исправления'; END IF;
        IF fix.kind = 'question' THEN
            UPDATE questions SET question_text = fix.new_text WHERE id = qid;
        ELSIF fix.kind = 'explanation' THEN
            PERFORM 1 FROM questions WHERE id = qid AND explanation IN (fix.old_text, fix.new_text);
            IF NOT FOUND THEN RAISE EXCEPTION 'Неожиданное пояснение вопроса'; END IF;
            UPDATE questions SET explanation = fix.new_text WHERE id = qid;
        ELSE
            SELECT count(*), min(o.key) INTO matches, k
            FROM questions q, jsonb_each_text(q.options) o
            WHERE q.id = qid AND o.value IN (fix.opt_text, coalesce(fix.new_opt_text, fix.opt_text));
            IF matches <> 1 THEN RAISE EXCEPTION 'Не найден единственный вариант ответа для исправления'; END IF;
            IF fix.new_text IS NOT NULL THEN
                PERFORM 1 FROM questions WHERE id = qid AND option_notes ->> k IN (fix.old_text, fix.new_text);
                IF NOT FOUND THEN RAISE EXCEPTION 'Неожиданное пояснение варианта'; END IF;
                UPDATE questions SET option_notes = jsonb_set(option_notes, ARRAY[k], to_jsonb(fix.new_text)) WHERE id = qid;
            END IF;
            IF fix.new_opt_text IS NOT NULL THEN
                UPDATE questions SET options = jsonb_set(options, ARRAY[k], to_jsonb(fix.new_opt_text)) WHERE id = qid;
            END IF;
        END IF;
    END LOOP;
END
$fix$;

COMMIT;
